(* [comment removed for export] *)
Lemma mb_cap_geom : forall es : list mbe,
  Forall (fun e => 512 <= snd e <= 2^31) es -> mb_geom es ->
  (es <> [] -> 2 ^ (Z.of_nat (length es) + 8) <= mb_cap es) /\ (2 <= Z.of_nat (length es) -> 2 ^ (Z.of_nat (length es) + 7) <= mb_capi es).
Proof.
  induction es as [| [x s] es IH] using rev_ind; intros F G.
  - split; [intros K; exfalso; exact (K eq_refl) | cbn; intros K; exfalso; lia].
  - assert (F' : Forall (fun e : mbe => 512 <= snd e <= 2^31) es) by (apply Forall_app in F; exact (proj1 F)).
    assert (G' : mb_geom es).
    { intros A y z C EQ. apply (G A y z (C ++ [(x, s)])). rewrite EQ. rewrite <- !app_assoc. reflexivity. }
    destruct (IH F' G') as [IH1 IH2]. clear IH.
    assert (S512 : 512 <= s) by (apply Forall_app in F; destruct F as [_ F2]; pose proof (Forall_inv F2) as K; cbn in K; lia).
    rewrite mb_cap_snoc, mb_capi_snoc, length_app. cbn [length]. rewrite Nat2Z.inj_add. cbn [Z.of_nat Pos.of_succ_nat].
    destruct es as [| e0 es0] eqn:EQes.
    + cbn. split; [intros _; lia | intros K; exfalso; lia].
    + rewrite <- EQes in *. assert (NE : es <> []) by (rewrite EQes; discriminate).
      pose proof (IH1 NE) as C1.
      assert (LEN1 : 1 <= Z.of_nat (length es)) by (rewrite EQes; cbn [length]; lia).
      split.
      * intros _. destruct (Z_lt_le_dec (Z.of_nat (length es)) 2) as [LT|GE].
        -- assert (L1 : Z.of_nat (length es) = 1) by lia. rewrite L1 in *. change (2 ^ (1 + 1 + 8)) with 1024. change (2 ^ (1 + 8)) with 512 in C1. lia.
        -- pose proof (IH2 GE) as C2.
           destruct (mb_es_snoc_inv es NE) as (A & y1 & y2 & EA).
           assert (GZ : 2 * mb_cap A <= s).
           { apply (G A (y1, y2) (x, s) []). rewrite EA, <- app_assoc. reflexivity. }
           unfold mb_capi in C2. replace (removelast es) with A in C2 by (rewrite EA, removelast_last; reflexivity).
           replace (2 ^ (Z.of_nat (length es) + 1 + 8)) with (2 * 2 ^ (Z.of_nat (length es) + 8)) by (rewrite <- Z.pow_succ_r by lia; f_equal; lia).
           replace (2 ^ (Z.of_nat (length es) + 8)) with (2 * 2 ^ (Z.of_nat (length es) + 7)) in * by (rewrite <- Z.pow_succ_r by lia; f_equal; lia).
           lia.
      * intros _. replace (Z.of_nat (length es) + 1 + 7) with (Z.of_nat (length es) + 8) by lia. exact C1.
Qed.

Lemma mb_len_bound : forall es insz M, mb_ok es insz -> mb_cap es < 2 ^ M -> 9 <= M -> Z.of_nat (length es) + 8 <= M.
Proof.
  intros es insz M (K1 & K2 & F & G) CAP HM.
  destruct (mb_cap_geom es F G) as [C1 _].
  destruct es as [| e es']; [cbn; lia|].
  pose proof (C1 ltac:(discriminate)) as C. 
  destruct (Z_lt_le_dec (Z.of_nat (length (e :: es')) + 8) (M + 1)) as [LT|GE]; [lia|].
  exfalso. assert (2 ^ M <= 2 ^ (Z.of_nat (length (e :: es')) + 8)) by (apply Z.pow_le_mono_r; lia). lia.
Qed.

(* [comment removed for export] *)
Lemma nodup_id_eq : forall (LB : list block) b1 b2, List.NoDup (map blk_id LB) -> In b1 LB -> In b2 LB -> blk_id b1 = blk_id b2 -> b1 = b2.
Proof.
  induction LB as [|b LB IH]; intros b1 b2 ND I1 I2 EQ; [destruct I1|].
  cbn in ND. apply List.NoDup_cons_iff in ND. destruct ND as [NI ND]. destruct I1 as [<-|I1], I2 as [<-|I2].
  - reflexivity.
  - exfalso. apply NI. rewrite EQ. apply in_map_iff. exists b2. split; [reflexivity | exact I2].
  - exfalso. apply NI. rewrite <- EQ. apply in_map_iff. exists b1. split; [reflexivity | exact I1].
  - apply IH; assumption.
Qed.

