Lemma elem_body_disjoint : forall s LB m mf Fa S L ns ls em mb_ b es insz,
  hs_RHEAP H s LB m -> FieldsC mf Fa S L ns ls em -> FieldsOwn LB em -> MBuf mb_ b es insz -> MBufOwn LB es ->
  (forall e x sz, e ∈ L -> In (x, sz) es -> e + 48 <= x \/ x + 24 + sz <= e) ->
  forall e d x sz, em !! e = Some d -> In (x, sz) es -> e + esize d <= x \/ x + 24 + sz <= e.
Proof.
  intros s LB m mf Fa S L ns ls em mb_ b es insz HP FC OWN MB MOWN DFB e d x sz Ld IN.
  pose proof FC as (_ & _ & _ & _ & _ & _ & _ & LEQ & _).
  destruct (OWN e d Ld) as [pe [I1 _]]. destruct (MOWN x sz IN) as [px I2].
  pose proof (mb_ok_size _ _ _ _ (proj2 MB) IN) as SZ. pose proof (mb_block_size_range sz ltac:(lia)) as [BR _]. pose proof (esize_ge d).
  assert (NE : blk_id (pe, e, esize d) <> blk_id (px, x, mb_block_size sz)).
  { intros EQ. pose proof (nodup_id_eq _ _ _ (hh_nodup H HH _ _ _ HP) I1 I2 EQ) as K. injection K as _ <- _.
    destruct (DFB e e sz ltac:(apply (proj2 (LEQ e)); rewrite Ld; eexists; reflexivity) IN); lia. }
  destruct (hh_disj H HH _ _ _ _ _ HP I1 I2 NE) as [D|D]; cbn in D; lia.
Qed.
