  mb_ok es insz -> 1 <= n -> 0 <= insz -> n <= R - (p - p0) -> insz + (R - (p - p0)) <= 2^28 ->
  mb_cap es <= 3 * insz + 512 -> Z.of_nat (length es) <= KB -> 0 <= hl ->
  lb_bytes LB + 17 * hl + body_res es insz (R - (p - p0)) + 34 <= MX' ->
  4 * Z.of_nat (length LB) + hl + 4 * (KB - Z.of_nat (length es)) + 0 + 2 <= 4 * CX' ->
     (mb_need es insz n = true -> lb_bytes LB + mb_block_size (mb_grow es insz n) <= MX' /\ Z.of_nat (length LB) + 1 <= CX')
  /\ forall (pp : bptr) (x : Z),
     (forall a34 a2, 0 <= a34 <= 34 -> 0 <= a2 <= 2 ->
        lb_bytes (mb_new_blocks es insz n pp x ++ LB) + 17 * hl + body_res (mb_put_es es insz n x) (insz + n) (R - (p + n - p0)) + a34 <= MX'
     /\ 4 * Z.of_nat (length (mb_new_blocks es insz n pp x ++ LB)) + hl + 4 * (KB - Z.of_nat (length (mb_put_es es insz n x))) + 0 + a2 <= 4 * CX'
     /\ insz + n + (R - (p + n - p0)) <= 2^28)
  /\ mb_cap (mb_put_es es insz n x) <= 3 * (insz + n) + 512 /\ Z.of_nat (length (mb_put_es es insz n x)) <= KB /\ 0 <= insz + n.
