Lemma put_round4 : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m0 : mem) (mo0 : Model) (LB0 : list block) (P E lo B : Z) (pad7 pad2 : list byte) (p0 R : Z) (bs : list byte)
    (L0 : list Z) (es0 : list mbe) (h0 : hdrv) (mb : byte) (p : Z) (cf : config),
  put_static H MX CX sp tp LB0 P E lo B p0 R bs -> p < p0 + Z.of_nat (length bs) ->
  put_at H MX CX 0x3978c (ak_st 4) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P E lo B pad7 pad2 p0 R bs L0 es0 h0 mb p cf ->
  hs_SR H (put_res H MX CX ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 mo0 LB0 P E lo B pad7 pad2 p0 R bs L0 es0 h0 mb p) cf.
Proof.
  intros until cf. intros STAT PLT AT.
  eapply (hh_seq H HH); [eapply put_call_pb; [exact STAT | exact PLT | exact AT] |].
  intros cf' (q & MID). eapply (put_common_SR H HH); [exact STAT | exact MID].
Qed.

